export function normalizeLongitude(value:number){return ((value+180)%360+360)%360-180;}
export function geographicVector(latitude:number,longitude:number,radius=1):[number,number,number]{const lat=latitude*Math.PI/180,lon=longitude*Math.PI/180;return [radius*Math.cos(lat)*Math.sin(lon),radius*Math.sin(lat),radius*Math.cos(lat)*Math.cos(lon)];}
export function vectorGeography(x:number,y:number,z:number){const radius=Math.hypot(x,y,z);return {latitude:Math.asin(Math.max(-1,Math.min(1,y/radius)))*180/Math.PI,longitude:normalizeLongitude(Math.atan2(x,z)*180/Math.PI)};}
